mapper.select:
select bm_requisition_received_material.*,bm_requisition_received_material.inventory_no as materialNo,bm_material.id as materialId,bm_material.merge_code as materialMergeCode
from bm_requisition_received_material
left join bm_material
on bm_material.platform_material_id = bm_requisition_received_material.platform_material_id
and bm_material.is_deleted = 0
where bm_requisition_received_material.requisition_plan_id = #{requisitionId}
  and bm_requisition_received_material.received_batch_id = #{receivedBatchId}
  and bm_material.id = #{materialId}
